import com.credits.scapi.v0.SmartContract;
import com.credits.scapi.v0.BasicStandard;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public class EBB extends SmartContract implements BasicStandard {
    private final String owner;
    private final String name = "EBB";
    private final String symbol = "EBB";
    private final int decimals = 18;
    private BigDecimal totalSupplyValue;
    private boolean frozen = false;
    private Map<String, BigDecimal> balances = new HashMap<>();
    private Map<String, Map<String, BigDecimal>> allowances = new HashMap<>();

    public EBB() { super(); owner = initiator; totalSupplyValue = new BigDecimal("1000000"); balances.put(owner, totalSupplyValue); }
    public String getName() { return name; }
    public String getSymbol() { return symbol; }
    public int getDecimal() { return decimals; }
    public String totalSupply() { return totalSupplyValue.toString(); }
    public String balanceOf(String a) { BigDecimal b = balances.get(a); return (b==null?BigDecimal.ZERO:b).toString(); }
    public boolean transfer(String to, String amount) { /* ... */ return true; }
    public boolean burn(String amount) { /* ... */ return true; }
    public boolean setFrozen(boolean f) { /* only owner */ return f; }
}
